
create table quizzes (id serial primary key,slug text unique not null,title text not null,subtitle text,instructions text not null,duration_min int not null,max_score numeric(4,1) not null,passing_score numeric(4,1) not null,levels jsonb not null,is_active boolean not null default true);
create table questions (id serial primary key,quiz_id int not null references quizzes(id) on delete cascade,position int not null,module text not null,text text not null,options jsonb not null,correct text not null check(correct in ('a','b','c','d')),explanation text not null,points numeric(3,1) not null default 1,unique(quiz_id,position));
create table candidates (id serial primary key,full_name text not null,agency text not null,email text,created_at timestamptz not null default now(),unique(full_name,agency));
create table attempts (id uuid primary key default gen_random_uuid(),quiz_id int not null references quizzes(id),candidate_id int not null references candidates(id) on delete cascade,token_hash text not null,status text not null default 'in_progress' check(status in ('in_progress','submitted','expired')),started_at timestamptz not null default now(),expires_at timestamptz not null,submitted_at timestamptz,duration_sec int,score numeric(4,1),max_score numeric(4,1) not null,passed boolean,level text);
create table answers (id serial primary key,attempt_id uuid not null references attempts(id) on delete cascade,question_id int not null references questions(id),revision bigint not null default 0,selected text check(selected is null or selected in ('a','b','c','d')),is_correct boolean,points numeric(3,1) not null default 0,answered_at timestamptz not null default now(),unique(attempt_id,question_id));
create table admin_users (id serial primary key,email text unique not null,password_hash text not null,full_name text not null,role text not null default 'admin' check(role in ('admin','viewer')),created_at timestamptz not null default now(),last_login_at timestamptz);
